 if(!csrf_check($_POST['csrf_token']??''))$error='Your session expired.';else{
  $action=(string)($_POST['action']??'save');$templateId=(int)($_POST['template_id']??0);
  if($action==='delete'){
   $old=document_template_by_id($templateId,false);if(!$old||(int)$old['investment_opportunity_id']!==$id)$error='Document template not found.';else{db()->prepare('DELETE FROM document_templates WHERE id=?')->execute([$templateId]);header('Location:opportunity.php?id='.$id.'&tab=documents&deleted=1');exit;}
